NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'II Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, nach der Verheißung des Lebens in Christo Jesu, an seinen geliebten Sohn Timotheus.',
        2: 'Gnade, Barmherzigkeit, Friede von Gott dem Vater, und unserem Herrn Jesus Christus.',
        3: 'Ich danke Gott, Dem ich diene mit reinem Gewissen, von meinen Voreltern her, daß ich ohne Unterlaß dein gedenke in meinen Gebeten Tag und Nacht,',
        4: 'Weil ich mich sehne, dich zu sehen, eingedenk deiner Tränen, auf daß ich mit Freude erfüllt würde;',
        5: 'Denn ich gedenke an deinen ungeheuchelten Glauben, der zuerst gewohnt hat in deiner Großmutter Lois und deiner Mutter Eunike; ich bin aber gewiß, daß er auch in dir wohnt;',
        6: 'Weshalb ich dich erinnere, daß du anfachst die Gabe Gottes, die durch Auflegung meiner Hände in dir ist.',
        7: 'Denn Gott hat uns nicht gegeben den Geist der Furcht, sondern der Kraft und der Liebe und der Zucht.',
        8: 'So schäme dich nun nicht des Zeugnisses von unserem Herrn, noch auch meiner, der gefangen ist um Seinetwillen, sondern trage mit die Leiden für das Evangelium vermöge der Kraft Gottes,',
        9: 'Der uns erlöst und berufen hat mit heiligem Ruf, nicht nach unseren Werken, sondern nach Seinem Ratschluß, und der uns in Christus Jesus vor ewigen Zeiten verliehenen Gnade,',
        10: 'Die aber jetzt geoffenbart ist durch die Erscheinung unseres Heilandes Jesus Christus, Der dem Tode die Macht genommen, und Leben und Unvergänglichkeit an das Licht gebracht hat durch das Evangelium,',
        11: 'Für welches ich bestellt bin als Herold, Apostel und Lehrer der Heiden.',
        12: 'Um welcher Ursache willen ich auch solches erleide, aber ich schäme mich dessen nicht; denn ich weiß, an Wen ich geglaubt habe, und bin gewiß, daß Er mächtig ist, das mir Anvertraute zu bewahren bis auf jenen Tag.',
        13: 'Halte an dem Vorbild der Heilsworte, die du von mir gehört in Glaube und Liebe in Christus Jesus.',
        14: 'Bewahre den kostbaren, dir anvertrauten Schatz durch den Heiligen Geist, der in uns wohnt.',
        15: 'Du weißt, daß sich von mir abgewendet haben alle in Asien, unter denen ist Phygellus und Hermogenes.',
        16: 'Der Herr schenke Barmherzigkeit dem Hause des Onesiphorus! Denn er hat mich oft erquickt, und hat sich meiner Kette nicht geschämt.',
        17: 'Sondern da er in Rom war, suchte er mich auf das Fleißigste und fand mich.',
        18: 'Der Herr lasse ihn an jenem Tage Barmherzigkeit finden vom Herrn; und wie große Dienste er in Ephesus geleistet hat, weißt du am besten.',
    },
    2: {
        1: 'Du nun, mein Sohn, erstarke in der Gnade in Christo Jesu!',
        2: 'Und was du von mir gehört hast vor vielen Zeugen, das vertraue treuen Menschen, die da tüchtig sind, auch andere zu lehren.',
        3: 'Du nun ertrage das Ungemach als ein wackerer Streiter Jesu Christi.',
        4: 'Keiner, der Kriegsdienste tut, mengt sich in die Händel des Lebens, auf daß er dem gefalle, der ihn in Dienst genommen hat.',
        5: 'Wenn einer aber auch kämpft, so wird er doch nicht gekrönt, er habe denn recht gekämpft.',
        6: 'Der arbeitende Ackersmann soll der Früchte am ersten genießen; merke dir, was ich sage!',
        7: 'Der Herr aber möge dir in allen Dingen Einsicht verleihen.',
        8: 'Halte im Gedächtnis Jesus Christus, Der von den Toten auferweckt worden aus dem Samen Davids, nach meinem Evangelium;',
        9: 'Über dem ich leide bis zu Banden, wie ein Übeltäter, aber das Wort Gottes ist nicht in Banden.',
        10: 'Darum erleide ich alles um der Auserwählten willen, auf daß auch sie des Heils in Christus Jesus mit ewiger Herrlichkeit teilhaftig werden.',
        11: 'Gewißlich wahr ist das Wort: Sterben wir mit, so werden wir auch mitleben.',
        12: 'Wenn wir ausharren, so werden wir auch mitherrschen; verleugnen wir, so wird auch Er uns verleugnen.',
        13: 'Wenn wir nicht treu sind, so bleibt doch Er treu, Er kann Sich Selbst nicht verleugnen.',
        14: 'Daran erinnere sie, indem du den Herrn zum Zeugen aufrufst, sie sollten kein Wortgezänke führen, das zu nichts nütze ist und nur der Zuhörer Sinn verkehrt.',
        15: 'Sei beflissen, dich vor Gott zu bewähren als einen Arbeiter, der sich nicht schämen darf, der mit dem Worte der Wahrheit recht umgeht.',
        16: 'Halte dich fern von ungeistlichen, losen Reden; denn sie helfen nur weiter in der Gottlosigkeit;',
        17: 'Und ihr Wort frißt um sich, wie der Krebs. Unter denen ist Hymenäus und Philetus,',
        18: 'Die von der Wahrheit abgewichen sind und sagen, die Auferstehung sei schon geschehen, und etliche in ihrem Glauben irre machen.',
        19: 'Aber der feste Grund Gottes besteht, und hat dieses Siegel: Der Herr kennt die Seinen, und von der Ungerechtigkeit stehe ab, wer immer den Namen des Herrn nennt.',
        20: 'In einem großen Hause aber sind nicht allein goldene und silberne Gefäße, sondern auch hölzerne und irdene, einige zu edlerem und einige zu unedlerem Gebrauch.',
        21: 'Wenn nun jemand sich rein hält von diesen, so wird er ein Gefäß zur Ehre, geweiht und brauchbar für den Hausherrn und bereitet zu jeglichem guten Werk.',
        22: 'Fliehe aber die jugendlichen Lüste, jage nach der Gerechtigkeit, dem Glauben, der Liebe, dem Frieden mit denen, die von reinem Herzen den Herrn anrufen.',
        23: 'Aber der törichten und albernen Streitfragen entschlage dich; denn du weißt, daß sie Wortkämpfe erzeugen.',
        24: 'Ein Knecht aber des Herrn soll nicht streiten, sondern liebreich sein gegen alle, tüchtig zum Lehren und Böses ertragen können.',
        25: 'Er soll mit Sanftmut die Widerspenstigen zurechtweisen, ob ihnen vielleicht Gott den Sinn zur Buße kehre, daß sie die Wahrheit erkennen.',
        26: 'Und wieder zu sich kommen aus der Schlinge des Teufels, in der sie von ihm für seinen Willen gefangengehalten wurden.',
    },
    3: {
        1: 'Das aber sollst du wissen, daß in den letzten Tagen arge Zeiten kommen werden.',
        2: 'Denn die Menschen werden sein eigenliebig, habsüchtig, ruhmredig, hoffärtig, Lästerer, den Eltern ungehorsam, undankbar, gottlos,',
        3: 'Lieblos, unversöhnlich, Verleumder, unkeusch, unbändig, dem Guten feind,',
        4: 'Verräterisch, verwegen, aufgeblasen, Sinnenlust mehr liebend denn Gott;',
        5: 'Die sich den Schein der Gottseligkeit geben, aber deren Kraft verleugnen; von solchen wende dich ab.',
        6: 'Zu diesen gehören die, so sich in die Häuser schleichen und die Weiblein an sich fesseln, die, mit Sünden beladen, von mancherlei Lüsten getrieben werden,',
        7: 'Die immerdar lernen und doch nie zur Erkenntnis der Wahrheit gelangen können.',
        8: 'Gleichwie Jannes und Jambres dem Mose widerstanden, also widerstehen auch diese der Wahrheit. Es sind Menschen verkehrten Sinnes, unbewährt im Glauben.',
        9: 'Aber sie werden es nicht in die Länge treiben; denn ihre Torheit wird allen offenbar werden, wie auch jener geworden ist.',
        10: 'Du aber bist meiner Lehre, meinem Wandel, meinem Ratschluß, meinem Glauben, meiner Langmut, meiner Liebe, meiner Beständigkeit gefolgt,',
        11: 'Ja meinen Verfolgungen, meinen Leiden, die mir widerfahren sind zu Antiochia, Ikonium und Lystra, welche Verfolgungen ich ertrug, und aus allen hat mich der Herr errettet.',
        12: 'Und alle, die in Christus Jesus gottselig leben wollen, müssen Verfolgungen erleiden.',
        13: 'Mit den Bösen aber wird es je länger je ärger werden; sie werden irre führen und selbst in der Irre gehen.',
        14: 'Du aber verbleibe bei dem, was du gelernt, und wovon du eine gewisse Überzeugung erlangt hast, da du ja weißt, von wem du es gelernt hast,',
        15: 'Und da du von Kindheit auf die heiligen Schriften kennst, die dich zur Seligkeit mittelst des Glaubens an Jesus Christus unterweisen können.',
        16: 'Alle Schrift, von Gott eingegeben, ist nütze zur Lehre, zur Rüge, zur Besserung, zur Zucht in der Gerechtigkeit,',
        17: 'Auf daß der Mensch aus Gott vollkommen zu jeglichem guten Werk geschickt sei.',
    },
    4: {
        1: 'Ich beschwöre dich nun vor Gott und Jesus Christus, Der da richten wird die Lebendigen und die Toten bei Seiner Erscheinung und in Seinem Reiche:',
        2: 'Predige das Wort, halte damit an zur gelegenen oder ungelegenen Zeit, rüge, warne, ermahne mit aller Langmut und Lehre.',
        3: 'Denn es wird eine Zeit kommen, wo sie die gesunde Lehre nicht ertragen, sondern nach eigenen Gelüsten sich mit Lehrern umgeben werden, die ihre Ohren kitzeln,',
        4: 'Und werden die Ohren von der Wahrheit abwenden und sich Märchen zuwenden.',
        5: 'Du aber bleibe nüchtern in allem, ertrage Beschwerde, verrichte das Werk eines Evangelisten und tue, was deines Amtes ist.',
        6: 'Denn schon werde ich geopfert und die Stunde meines Hinscheidens naht.',
        7: 'Ich habe einen guten Kampf gekämpft, ich habe den Lauf vollendet, ich habe den Glauben bewahrt.',
        8: 'Schon liegt für mich bereit die Krone der Gerechtigkeit, die mir an jenem Tage der Herr, Der gerechte Richter, geben wird, aber nicht allein mir, sondern allen, die Seine Erscheinung lieb haben.',
        9: 'Beeile dich, daß du bald zu mir kommst.',
        10: 'Denn Demas hat mich verlassen und diese Welt lieb gewonnen, und ist gezogen nach Thessalonich, Crescens nach Galatien, Titus nach Dalmatien.',
        11: 'Lukas ist allein bei mir, Markus nimm zu dir, und bringe ihn mit dir, er ist mir nützlich zum Dienst.',
        12: 'Tychikus habe ich nach Ephesus gesandt.',
        13: 'Den Mantel, den ich bei Karpus in Troas gelassen, bringe mit, wenn du kommst, auch die Bücher, sonderlich aber die Pergamentrollen.',
        14: 'Alexander, der Schmied, hat mir viel Böses erwiesen; der Herr vergelte ihm nach seinen Werken!',
        15: 'Auch du hüte dich vor ihm; denn er ist unseren Worten sehr entgegengetreten.',
        16: 'In meiner ersten Verantwortung stand mir niemand zur Seite; alle verließen mich möge es ihnen nicht angerechnet werden!',
        17: 'Der Herr aber stand mir bei und schenkte mir Kraft, auf daß durch mich die Predigt bestätigt würde und alle Heiden sie hörten, und ich bin aus des Löwen Rachen erlöst.',
        18: 'Und der Herr wird mich erlösen von allem Übel und mich retten in Sein Himmelreich. Ihm sei Ehre von Ewigkeit zu Ewigkeit! Amen.',
        19: 'Grüße Prisca und Aquila und das Haus des Onesiphorus.',
        20: 'Erastus blieb in Korinth, den Trophimus ließ ich krank in Milet zurück.',
        21: 'Beeile dich, daß du noch vor dem Winter kommst. Es grüßt dich Eubulus und Pudens und Linus und Claudia und die Brüder alle.',
        22: 'Der Herr Jesus Christus sei mit deinem Geiste! Die Gnade sei mit euch!',
    },
}
